stage = 0
fwd = 0.0

def control(obs):
    global stage, fwd
    st = obs.get('status')
    mot = obs.get('motion') or {}
    v = mot.get('v_mps', 0.0) or 0.0
    dt = obs.get('dt', 0.1) or 0.1
    h = obs.get('hitch_deg', 0.0) or 0.0
    rig = obs.get('rig') or {}
    tr = rig.get('trailer_rear', [-1.6, 0.0])
    y = tr[1]
    if st in ('PINNED', 'JACKKNIFED'):
        stage = 0
        fwd = 0.0
    if stage == 0:
        if v > 0:
            fwd += v * dt
        if fwd >= 0.9:
            stage = 1
        return (-45.0, 0.5, 180)
    if abs(h) > 40:
        stage = 0
        fwd = 0.0
        return (-45.0, 0.5, 180)
    steer = 2.5 * h + 8.0 * (y + 0.2)
    steer = max(-30.0, min(30.0, steer))
    return (steer, -0.4, 180)

